// aim.cpp
// World-to-screen projection + smoothed crosshair delta within a 240 px cone.
//
// Build (standalone smoke test):
//   cl /std:c++17 /DSMOKE_TEST /O2 /W4 aim.cpp /link user32.lib
//
// Exported helpers (call from your game loop):
//   bool  WorldToScreen(Vec3 world, Vec2& screen, const float vpm[16], int sw, int sh)
//   Vec2  AimDelta(Vec2 targetScreen, Vec2 crosshair, float smoothing)
//   bool  InCone(Vec2 targetScreen, Vec2 crosshair, float radiusPx = 240.f)

#include <windows.h>
#include <cmath>
#include <optional>

// ---------------------------------------------------------------------------
// Minimal math types (no external SDK)
// ---------------------------------------------------------------------------

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };

static inline Vec2 operator-(Vec2 a, Vec2 b) { return {a.x - b.x, a.y - b.y}; }
static inline Vec2 operator+(Vec2 a, Vec2 b) { return {a.x + b.x, a.y + b.y}; }
static inline Vec2 operator*(Vec2 v, float s) { return {v.x * s, v.y * s}; }

static inline float Length(Vec2 v)
{
    return std::sqrtf(v.x * v.x + v.y * v.y);
}

// ---------------------------------------------------------------------------
// WorldToScreen
//
// vpm : column-major 4x4 view-projection matrix (OpenGL / D3D both work once
//       you've built the matrix consistently).
//       vpm[col * 4 + row]  — same layout as glUniformMatrix4fv default.
//
// Returns false when the point is behind the camera (w <= 0).
// ---------------------------------------------------------------------------
bool WorldToScreen(Vec3 world, Vec2& screen, const float vpm[16], int sw, int sh)
{
    // Multiply [world | 1] by the view-projection matrix.
    // vpm is column-major: element (row r, col c) lives at vpm[c*4 + r].
    const float x = world.x, y = world.y, z = world.z;

    float cx = vpm[0]*x + vpm[4]*y + vpm[8]*z  + vpm[12];
    float cy = vpm[1]*x + vpm[5]*y + vpm[9]*z  + vpm[13];
    // cz unused for 2-D projection
    float cw = vpm[3]*x + vpm[7]*y + vpm[11]*z + vpm[15];

    if (cw <= 0.f)
        return false;   // behind camera

    float invW = 1.f / cw;
    float ndcX =  cx * invW;   // [-1, 1]
    float ndcY =  cy * invW;   // [-1, 1] (Y-up in clip space)

    // Convert NDC → pixel coords (Y flipped so +Y is down on screen).
    screen.x = ( ndcX + 1.f) * 0.5f * static_cast<float>(sw);
    screen.y = (-ndcY + 1.f) * 0.5f * static_cast<float>(sh);
    return true;
}

// ---------------------------------------------------------------------------
// InCone
//
// Returns true when targetScreen is within radiusPx pixels of crosshair.
// 240 px default matches the spec.
// ---------------------------------------------------------------------------
bool InCone(Vec2 targetScreen, Vec2 crosshair, float radiusPx)
{
    Vec2 delta = targetScreen - crosshair;
    return Length(delta) <= radiusPx;
}

// ---------------------------------------------------------------------------
// AimDelta
//
// Computes the per-frame delta the crosshair should move toward targetScreen.
// smoothing : [0, 1) — fraction of the remaining distance to cover this frame.
//             0.0 = instant snap; 0.9 = very slow follow.
//
// Typical game-loop usage:
//   if (InCone(headScreen, crosshairPos)) {
//       Vec2 d = AimDelta(headScreen, crosshairPos, smoothing);
//       crosshairPos = crosshairPos + d;   // or feed to mouse_event / SendInput
//   }
// ---------------------------------------------------------------------------
Vec2 AimDelta(Vec2 targetScreen, Vec2 crosshair, float smoothing)
{
    // Clamp smoothing so we never overshoot or divide by zero.
    if (smoothing < 0.f) smoothing = 0.f;
    if (smoothing > 0.9999f) smoothing = 0.9999f;

    Vec2  diff = targetScreen - crosshair;
    float step = 1.f - smoothing;   // fraction of distance to close per frame
    return diff * step;
}

// ---------------------------------------------------------------------------
// Convenience: project + gate in one call.
//
// Returns the smoothed delta toward the entity's head if it is on-screen and
// inside the 240 px cone, otherwise returns nullopt.
// ---------------------------------------------------------------------------
std::optional<Vec2> AimAtHead(
    Vec3        headWorld,
    Vec2        crosshair,
    const float vpm[16],
    int         screenW,
    int         screenH,
    float       smoothing  = 0.1f,
    float       conePx     = 240.f)
{
    Vec2 headScreen{};
    if (!WorldToScreen(headWorld, headScreen, vpm, screenW, screenH))
        return std::nullopt;

    if (!InCone(headScreen, crosshair, conePx))
        return std::nullopt;

    return AimDelta(headScreen, crosshair, smoothing);
}

// ---------------------------------------------------------------------------
// Standalone smoke test
// ---------------------------------------------------------------------------
#ifdef SMOKE_TEST
#include <cstdio>

// Build a trivial orthographic-ish view-projection matrix for testing.
// Column-major, maps world XY directly to NDC, Z ignored.
static void MakeTestVPM(float out[16], int sw, int sh)
{
    // Identity then scale so world unit 1 = NDC 0.1
    for (int i = 0; i < 16; ++i) out[i] = 0.f;
    out[0]  =  0.1f;    // col0 row0
    out[5]  =  0.1f;    // col1 row1
    out[10] =  0.1f;    // col2 row2
    out[15] =  1.f;     // col3 row3  (w = 1)
    (void)sw; (void)sh;
}

int main()
{
    const int W = 1920, H = 1080;
    float vpm[16];
    MakeTestVPM(vpm, W, H);

    // --- WorldToScreen ---
    Vec3 head{ 1.f, 2.f, 5.f };
    Vec2 screen{};
    bool visible = WorldToScreen(head, screen, vpm, W, H);
    printf("WorldToScreen: visible=%d  screen=(%.1f, %.1f)\n",
           (int)visible, screen.x, screen.y);

    // --- InCone ---
    Vec2 crosshair{ static_cast<float>(W)/2.f, static_cast<float>(H)/2.f };
    bool inside = InCone(screen, crosshair, 240.f);
    printf("InCone(r=240): %s  dist=%.1f px\n",
           inside ? "YES" : "NO",
           Length(screen - crosshair));

    // --- AimDelta ---
    Vec2 delta = AimDelta(screen, crosshair, 0.85f);
    printf("AimDelta(smooth=0.85): (%.3f, %.3f)\n", delta.x, delta.y);

    // --- AimAtHead convenience ---
    auto result = AimAtHead(head, crosshair, vpm, W, H, 0.85f, 240.f);
    if (result)
        printf("AimAtHead delta: (%.3f, %.3f)\n", result->x, result->y);
    else
        printf("AimAtHead: target outside cone or behind camera\n");

    return 0;
}
#endif // SMOKE_TEST
